create table public.notification_templates(id uuid primary key default gen_random_uuid(),key citext not null unique,channel text not null,title_template text not null,body_template text not null,is_active boolean not null default true,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()));
create table public.notifications(id uuid primary key default gen_random_uuid(),recipient_id uuid not null references public.profiles(id) on delete cascade,actor_id uuid references public.profiles(id) on delete set null,notification_type text not null,title text not null,body text not null,entity_type text,entity_id uuid,metadata jsonb not null default '{}'::jsonb,read_at timestamptz,archived_at timestamptz,created_at timestamptz not null default timezone('utc',now()),constraint notification_metadata check(jsonb_typeof(metadata)='object'));
create table public.notification_deliveries(id uuid primary key default gen_random_uuid(),notification_id uuid not null references public.notifications(id) on delete cascade,channel text not null,status text not null default 'pending',provider_reference text,attempted_at timestamptz,created_at timestamptz not null default timezone('utc',now()));create index notifications_recipient_idx on public.notifications(recipient_id,created_at desc);create index notifications_unread_idx on public.notifications(recipient_id,created_at desc) where read_at is null;alter table public.notification_templates enable row level security;alter table public.notifications enable row level security;alter table public.notification_deliveries enable row level security;create policy notification_templates_read on public.notification_templates for select to authenticated using(true);create policy notification_templates_manage on public.notification_templates for all to authenticated using(public.has_permission('notifications.manage')) with check(public.has_permission('notifications.manage'));create policy notifications_owner on public.notifications for select to authenticated using(recipient_id=auth.uid());create policy notifications_update_owner on public.notifications for update to authenticated using(recipient_id=auth.uid()) with check(recipient_id=auth.uid());create policy deliveries_admin on public.notification_deliveries for select to authenticated using(public.has_permission('notifications.manage'));
